#include <Arduino.h>
const int buttonPin = 4;
const int ledPin = 2; // Use an external LED with a resistor if this pin has no onboard LED.
volatile bool eventReady = false;
void IRAM_ATTR onEdge() { eventReady = true; }
void setup() {
    pinMode(buttonPin, INPUT_PULLUP);
    pinMode(ledPin, OUTPUT);
    attachInterrupt(digitalPinToInterrupt(buttonPin), onEdge, FALLING);
}
void loop() {
    if (eventReady) { noInterrupts(); eventReady = false; interrupts(); digitalWrite(ledPin, !digitalRead(ledPin)); }
    delay(1);
}

#include <Arduino.h>
const int pin = 2; // Use an external LED with a resistor if needed.
void setup() { pinMode(pin, OUTPUT); }
void loop() { digitalWrite(pin, !digitalRead(pin)); delay(500); }
